Object.assign(window.EL_CAPSULES, {
  "p5:Oct:1": {"title": "Un imperio donde nunca se ponía el sol", "steps": [{"type": "hook", "kicker": "Historia viva", "h": "¿Te imaginas un país tan grande que, mientras anochece en una parte, en otra amanece?", "scenario": "Corre el año 1580. Un niño de tu edad que viviera en aquella época podría decir que su rey gobierna tierras en Europa, América y Asia, todas a la vez.", "body": "En el siglo XVI, el <b>Imperio español</b> alcanzó su máxima extensión. Sus territorios eran tan numerosos y estaban tan repartidos por el mundo que la gente decía que en él <b>nunca se ponía el sol</b>: siempre había una zona del imperio donde era de día."}, {"type": "theory", "kicker": "Lo esencial", "h": "El Imperio español en su apogeo (1580)", "body": "Hacia 1580, bajo el reinado de <b>Felipe II</b>, España gobernaba un territorio inmenso: la <b>Península Ibérica</b> (incluida Portugal, unida a la corona ese mismo año), posesiones en <b>Italia</b> (Nápoles, Sicilia, Milán), los <b>Países Bajos</b> en el norte de Europa, y enormes territorios en <b>América</b> (los virreinatos de Nueva España y Perú), además de las <b>Filipinas</b>, en Asia. Por tierra y mar, España se convirtió en la mayor potencia del mundo conocido.", "diagram": "IMPERIO ESPAÑOL (1580)<br><b>Europa:</b> España, Portugal, Países Bajos, Nápoles, Sicilia, Milán<br><b>América:</b> Nueva España, Perú<br><b>Asia:</b> Filipinas<br>→ el imperio donde nunca se ponía el sol"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué país europeo se unió a la corona española en 1580?", "q": "¿Qué país europeo se unió a la corona española en 1580?", "opts": [{"t": "Portugal", "ok": true}, {"t": "Francia", "ok": false}, {"t": "Inglaterra", "ok": false}, {"t": "Italia", "ok": false}], "okMsg": "¡Correcto! En 1580 Portugal se unió a la corona española, y así el imperio alcanzó su mayor extensión.", "noMsg": "No es esa. Fue Portugal el que se unió a la corona española en 1580."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cartógrafo real por un día", "body": "Vas a convertirte en cartógrafo de la corte de Felipe II. Busca o dibuja un mapa del mundo en 1580 y localiza los territorios del Imperio español.", "prompt": "Dibuja o pega un mapamundi en tu cuaderno y colorea de un mismo color los territorios que pertenecían al Imperio español hacia 1580 (España, Portugal, Países Bajos, parte de Italia, América y Filipinas). Añade una leyenda con los nombres de cada territorio."}]},
  "p5:Oct:2": {"title": "Dos reyes, un mismo linaje", "steps": [{"type": "hook", "kicker": "Historia viva", "h": "¿Puede un padre y un hijo gobernar de forma tan distinta?", "scenario": "Carlos I viajó por media Europa dirigiendo ejércitos y reinos; su hijo Felipe II apenas salió de España y gobernó durante décadas desde un único palacio. Ambos fueron reyes poderosos, pero de manera muy diferente.", "body": "<b>Carlos I</b> (1516-1556) fue el primer rey que gobernó todos los reinos de España unidos, y además fue emperador del <b>Sacro Imperio Romano Germánico</b>. Su hijo <b>Felipe II</b> (1556-1598) heredó ese inmenso territorio y lo gobernó desde España, defendiendo con firmeza la fe católica."}, {"type": "theory", "kicker": "Lo esencial", "h": "Carlos I y Felipe II: dos formas de reinar", "body": "<b>Carlos I</b> fue un rey viajero: recorrió Europa gobernando personalmente sus territorios y luchando en numerosas guerras. <b>Felipe II</b>, en cambio, prefirió gobernar desde un único lugar, España, rodeado de sus consejeros y ayudado por un enorme papeleo administrativo. Ambos compartían el mismo objetivo: defender la fe católica y mantener unido el imperio, aunque con estilos de gobierno muy distintos.", "diagram": "CARLOS I<br>Rey viajero · Emperador · Gobierna en persona por Europa<br><br>FELIPE II<br>Rey de los papeles · Gobierna desde España · Defensor de la fe católica<br><br>EN COMÚN: misma dinastía, misma fe, un imperio inmenso"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Cómo gobernaba Felipe II?", "q": "¿Cuál de estas afirmaciones describe mejor a Felipe II?", "opts": [{"t": "Gobernó principalmente desde España, sin viajar tanto como su padre", "ok": true}, {"t": "Nunca gobernó ningún territorio", "ok": false}, {"t": "Fue el primer rey de España unida", "ok": false}, {"t": "Vivió antes que Carlos I", "ok": false}], "okMsg": "¡Correcto! Felipe II gobernó su inmenso imperio principalmente desde España.", "noMsg": "No es esa. Felipe II gobernó sobre todo desde España, a diferencia de su padre, que viajaba constantemente."}, {"type": "reflect", "kicker": "Tu turno", "h": "Carlos I frente a Felipe II", "body": "Elabora una comparación entre estos dos reyes tan importantes de la historia de España.", "prompt": "Haz una tabla en tu cuaderno con dos columnas, una para Carlos I y otra para Felipe II. Escribe 3 diferencias y 3 semejanzas entre ambos reyes."}]},
  "p5:Oct:3": {"title": "Un palacio, un monasterio, una fe", "steps": [{"type": "hook", "kicker": "Historia viva", "h": "¿Puede un edificio contar la historia de la fe de un rey?", "scenario": "Felipe II ordenó construir un edificio enorme en la sierra de Madrid: mitad palacio, mitad monasterio, mitad biblioteca. Quería un lugar donde gobernar y también donde orar.", "body": "Ese edificio es <b>El Escorial</b>, uno de los monumentos más importantes de España. En él, Felipe II combinó su papel de rey con su profunda fe cristiana."}, {"type": "theory", "kicker": "Lo esencial", "h": "El Escorial: fe y poder unidos en piedra", "body": "El <b>Monasterio de El Escorial</b> fue mandado construir por <b>Felipe II</b> en el siglo XVI. Cumplía varias funciones a la vez: era <b>palacio real</b> (desde donde gobernaba el imperio), <b>monasterio</b> (con monjes que oraban allí cada día), <b>biblioteca</b> (con miles de libros) y <b>panteón real</b> (lugar de enterramiento de los reyes). Su construcción refleja cómo, para Felipe II, el poder de gobernar y la fe cristiana estaban profundamente unidos.", "diagram": "EL ESCORIAL<br><b>Mandado construir por:</b> Felipe II<br><b>Funciones:</b> palacio + monasterio + biblioteca + panteón real<br><b>Significado:</b> unión entre el poder del rey y la fe cristiana"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué función NO cumplía El Escorial?", "q": "¿Cuál de estas opciones NO era una función de El Escorial?", "opts": [{"t": "Puerto marítimo", "ok": true}, {"t": "Monasterio", "ok": false}, {"t": "Biblioteca", "ok": false}, {"t": "Panteón real", "ok": false}], "okMsg": "¡Correcto! El Escorial nunca fue un puerto marítimo, sino palacio, monasterio, biblioteca y panteón real.", "noMsg": "No es esa. Esa función sí la cumplía El Escorial. La opción correcta era 'Puerto marítimo', algo que nunca fue."}, {"type": "reflect", "kicker": "Tu turno", "h": "Investiga El Escorial", "body": "Investiga sobre El Escorial y descubre por qué es un lugar tan especial en la historia de España.", "prompt": "Busca información (en un libro, enciclopedia o con ayuda de un adulto) sobre El Escorial y responde en tu cuaderno: ¿quién lo mandó construir?, ¿para qué servía?, ¿qué crees que representa la unión entre palacio y monasterio en un mismo edificio?"}]},
  "p5:Oct:4": {"title": "El rey que gobierna con justicia", "steps": [{"type": "hook", "kicker": "Un versículo, una enseñanza", "h": "¿Qué hace que un rey sea recordado como bueno o como malo?", "scenario": "Carlos I y Felipe II gobernaron territorios inmensos, con mucho poder en sus manos. La Biblia ya advertía, siglos antes, sobre cómo debía usarse ese poder.", "body": "En <b>Proverbios 29:14</b> leemos: <i>El rey que juzga con verdad a los pobres, afirmará su trono para siempre.</i> Este versículo enseña que el verdadero poder de un gobernante no está en la extensión de sus territorios, sino en si gobierna con <b>justicia</b>."}, {"type": "theory", "kicker": "Lo esencial", "h": "Proverbios 29:14: el poder al servicio de la justicia", "body": "La Biblia enseña que un buen gobernante debe preocuparse especialmente por los más débiles y necesitados, los <b>pobres</b>. Un imperio puede ser enorme, como el de Carlos I y Felipe II, pero lo que de verdad hace que un gobierno perdure es la <b>justicia</b> con la que se trata a todas las personas, no solo el tamaño de sus territorios.", "diagram": "PROVERBIOS 29:14<br>El rey que juzga con verdad a los pobres, afirmará su trono para siempre<br><br>PODER + JUSTICIA = gobierno que perdura<br>PODER SIN JUSTICIA = trono débil"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué afirma el trono de un rey, según Proverbios 29:14?", "q": "Según Proverbios 29:14, ¿qué afirma el trono de un rey para siempre?", "opts": [{"t": "Juzgar con verdad a los pobres", "ok": true}, {"t": "Tener muchos territorios", "ok": false}, {"t": "Construir muchos palacios", "ok": false}, {"t": "Ganar todas las guerras", "ok": false}], "okMsg": "¡Correcto! Juzgar con verdad a los pobres es lo que, según la Biblia, afirma el trono de un rey para siempre.", "noMsg": "No es esa. Proverbios 29:14 dice que es juzgar con verdad a los pobres lo que afirma el trono de un rey."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cierre del mes: imperio y justicia", "body": "Reflexiona sobre lo que has aprendido este mes sobre el Imperio español y relaciónalo con la enseñanza bíblica de hoy.", "prompt": "Escribe en tu cuaderno una reflexión breve (5-6 líneas): ¿por qué crees que un imperio tan grande como el de Carlos I y Felipe II necesitaba reyes justos? Después, entrega tu 'Trabajo El Imperio Español' recogiendo lo aprendido durante todo el mes."}]},
  "p5:Nov:1": {"title": "España en el mapa de Europa", "steps": [{"type": "hook", "kicker": "Geografía viva", "h": "¿Con qué países comparte España sus fronteras?", "scenario": "Si viajaras en coche desde tu casa hacia el norte o hacia el oeste, en pocas horas podrías cruzar la frontera y estar en otro país, con otro idioma y otra capital.", "body": "España está situada en el suroeste de Europa, formando parte de la <b>Península Ibérica</b>. A su alrededor tiene varios países vecinos con los que comparte frontera terrestre o marítima."}, {"type": "theory", "kicker": "Lo esencial", "h": "España y sus países fronterizos", "body": "España limita al oeste con <b>Portugal</b> (capital <b>Lisboa</b>), al norte con <b>Francia</b> (capital <b>París</b>) y con el pequeño país de <b>Andorra</b> (capital <b>Andorra la Vieja</b>). Al sur, muy cerca de la costa, se encuentra <b>Marruecos</b> (capital <b>Rabat</b>), separado por el estrecho de Gibraltar.", "diagram": "ESPAÑA Y SUS VECINOS<br>Portugal → Lisboa (oeste)<br>Francia → París (norte)<br>Andorra → Andorra la Vieja (norte, Pirineos)<br>Marruecos → Rabat (sur, al otro lado del estrecho)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Cuál es la capital de Portugal?", "q": "¿Cuál es la capital de Portugal, el país vecino de España al oeste?", "opts": [{"t": "Lisboa", "ok": true}, {"t": "Oporto", "ok": false}, {"t": "Madrid", "ok": false}, {"t": "París", "ok": false}], "okMsg": "¡Correcto! Lisboa es la capital de Portugal, el vecino de España al oeste.", "noMsg": "No es esa. La capital de Portugal es Lisboa."}, {"type": "reflect", "kicker": "Tu turno", "h": "Manos a la obra con el mapa", "body": "Ponte manos a la obra con el mapa de Europa que iniciarás este mes.", "prompt": "Dibuja o imprime un mapa de Europa. Colorea España de un color y sus países fronterizos (Portugal, Francia, Andorra) de otros colores distintos. Escribe junto a cada país el nombre de su capital."}]},
  "p5:Nov:2": {"title": "España, un país europeo", "steps": [{"type": "hook", "kicker": "Geografía viva", "h": "¿Qué gana España por formar parte de un grupo de países?", "scenario": "Cuando viajas a Francia o a Italia con tu familia, no necesitas cambiar de moneda ni enseñar el pasaporte en la frontera. Esto no siempre fue así.", "body": "España forma parte de la <b>Unión Europea (UE)</b>, una organización que une a varios países europeos para colaborar en economía, leyes y otros muchos ámbitos."}, {"type": "theory", "kicker": "Lo esencial", "h": "España en la Unión Europea: aportaciones y beneficios", "body": "España aporta a la Unión Europea su <b>economía</b> (turismo, agricultura, industria) y su <b>voz política</b> en las decisiones conjuntas de Europa. A cambio, recibe importantes <b>beneficios</b>: <b>fondos económicos</b> para mejorar carreteras, hospitales o escuelas, y la posibilidad de que sus ciudadanos <b>viajen, estudien y trabajen libremente</b> en cualquier país de la UE.", "diagram": "ESPAÑA EN LA UE<br>APORTA: economía, voz política<br>RECIBE: fondos europeos, libre circulación de personas<br>Moneda común: el euro"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué beneficio recibe España de la UE?", "q": "¿Cuál de estos es un beneficio que España recibe por pertenecer a la Unión Europea?", "opts": [{"t": "Fondos económicos y libre circulación de personas", "ok": true}, {"t": "Perder su propio idioma", "ok": false}, {"t": "No poder comerciar con otros países", "ok": false}, {"t": "Tener que cambiar de capital", "ok": false}], "okMsg": "¡Correcto! España recibe fondos europeos y sus ciudadanos pueden moverse libremente por la Unión Europea.", "noMsg": "No es esa. España recibe, entre otras cosas, fondos económicos y libre circulación de personas."}, {"type": "reflect", "kicker": "Tu turno", "h": "Tu ficha de España en la UE", "body": "Elabora tu ficha personal sobre España y la Unión Europea.", "prompt": "Haz una ficha en tu cuaderno titulada 'España en la UE'. Escribe 2 aportaciones que hace España a Europa y 2 beneficios que recibe a cambio. Puedes ilustrarla con la bandera europea."}]},
  "p5:Nov:3": {"title": "España, grande entre gigantes", "steps": [{"type": "hook", "kicker": "Geografía viva", "h": "¿Es España un país grande o pequeño comparado con sus vecinos europeos?", "scenario": "A veces pensamos que España es un país pequeño, pero al comparar su tamaño con el de otros países europeos, la sorpresa puede ser grande.", "body": "España tiene una extensión de unos <b>505.000 km²</b>, lo que la convierte en uno de los países más grandes de la Unión Europea, aunque hay otros con más superficie."}, {"type": "theory", "kicker": "Lo esencial", "h": "La extensión de España comparada con Francia, Alemania e Italia", "body": "<b>Francia</b> es el país más extenso de esta comparación, con más de <b>550.000 km²</b>. <b>España</b>, con unos <b>505.000 km²</b>, es el segundo país más grande de este grupo. <b>Alemania</b> tiene unos <b>357.000 km²</b> e <b>Italia</b> unos <b>301.000 km²</b>. Aunque tienen tamaños distintos, los cuatro países forman parte destacada de la Unión Europea.", "diagram": "EXTENSIÓN (km²)<br>Francia: +550.000<br>España: ~505.000<br>Alemania: ~357.000<br>Italia: ~301.000"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué país tiene mayor extensión que España?", "q": "Según esta comparación, ¿qué país tiene mayor extensión que España?", "opts": [{"t": "Francia", "ok": true}, {"t": "Alemania", "ok": false}, {"t": "Italia", "ok": false}, {"t": "Portugal", "ok": false}], "okMsg": "¡Correcto! Francia es más extensa que España, aunque España supera a Alemania e Italia.", "noMsg": "No es esa. De estos cuatro países, Francia es el que tiene mayor extensión que España."}, {"type": "reflect", "kicker": "Tu turno", "h": "Compara los territorios", "body": "Organiza la información sobre la extensión de estos países en una actividad visual.", "prompt": "Dibuja en tu cuaderno un gráfico de barras (puede ser sencillo, con cuadrados de distinto tamaño) comparando la extensión de España, Francia, Alemania e Italia. Ordénalos de mayor a menor."}]},
  "p5:Nov:4": {"title": "Un mismo origen, fronteras distintas", "steps": [{"type": "hook", "kicker": "Un versículo, una enseñanza", "h": "¿Por qué existen fronteras si todos los seres humanos venimos del mismo origen?", "scenario": "Este mes has aprendido que España tiene fronteras con varios países y forma parte de la Unión Europea junto a otros. Pero, ¿de dónde viene esta diversidad de naciones?", "body": "En <b>Hechos 17:26</b> leemos: <i>De una sangre ha hecho Dios todo el linaje humano, para que habite la tierra.</i> Este versículo enseña que, aunque existan fronteras y naciones distintas, todos los seres humanos compartimos un mismo origen."}, {"type": "theory", "kicker": "Lo esencial", "h": "Hechos 17:26: un origen común, límites señalados por Dios", "body": "Según la Biblia, Dios creó a toda la humanidad de un mismo origen y fijó los <b>límites de las naciones</b>. Esto significa que las <b>fronteras</b> entre países como España, Portugal o Francia no separan a personas de distinto valor, sino que forman parte de un orden que permite a cada pueblo habitar su territorio, sin que eso anule lo que todos tenemos en común como seres humanos.", "diagram": "HECHOS 17:26<br>De una sangre ha hecho Dios todo el linaje humano, para que habite la tierra<br><br>UN SOLO ORIGEN + FRONTERAS Y NACIONES<br>= diversidad dentro de una misma familia humana"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué enseña Hechos 17:26 sobre el origen humano?", "q": "Según Hechos 17:26, ¿qué ha hecho Dios con todo el linaje humano?", "opts": [{"t": "Crearlo de un mismo origen", "ok": true}, {"t": "Darle fronteras sin ningún propósito", "ok": false}, {"t": "Separarlo en pueblos enemigos entre sí", "ok": false}, {"t": "Impedir que existan las naciones", "ok": false}], "okMsg": "¡Correcto! Hechos 17:26 enseña que Dios hizo a toda la humanidad de un mismo origen.", "noMsg": "No es esa. El versículo enseña que Dios ha hecho de un mismo origen a todo el linaje humano."}, {"type": "reflect", "kicker": "Tu turno", "h": "Cierre del mes: España, Europa y un mismo origen", "body": "Cierra el mes reuniendo todo lo aprendido sobre España en Europa y esta enseñanza bíblica.", "prompt": "En tu cuaderno, completa tu 'Mapa de España en Europa + ficha de la UE' y añade una frase final explicando, con tus propias palabras, qué significa para ti que todos los seres humanos compartamos un mismo origen aunque vivamos en países distintos."}]},
  "p5:Dic:1": {"title": "Tesis, argumentos y conclusión: el arte de convencer con razones", "steps": [{"type": "hook", "kicker": "Semana 1 · Diciembre", "h": "¿Se puede ganar una discusión sin levantar la voz?", "scenario": "En la sobremesa, tu primo mayor afirma: \"La Reconquista fue lo mejor que le pudo pasar a España\". Tú no estás tan seguro, pero no sabes cómo rebatirle con algo más que un \"pues no\".", "body": "Este mes vas a aprender a construir <b>textos argumentativos</b>: textos que defienden una idea con razones, no con gritos. Para convencer de verdad hace falta una <b>tesis</b> clara, <b>argumentos</b> sólidos y una <b>conclusión</b> que cierre el razonamiento. Vamos a practicarlo con un tema histórico muy debatido: la Reconquista."}, {"type": "theory", "kicker": "Teoría", "h": "Las tres piezas de todo texto argumentativo", "body": "Un texto argumentativo bien construido tiene siempre tres partes. La <b>tesis</b> es la idea principal que se quiere defender, normalmente al principio del texto. Los <b>argumentos</b> son las razones, datos o ejemplos que sostienen esa tesis (lo más convincente es usar datos históricos concretos, no solo opiniones). La <b>conclusión</b> retoma la tesis y cierra el texto, a veces reforzándola con una idea final. Sin estas tres piezas, un texto es solo una opinión suelta, no una argumentación.", "diagram": "<b>TESIS</b> (la idea que defiendo)<br>↓<br><b>ARGUMENTO 1</b> (dato histórico)<br><b>ARGUMENTO 2</b> (dato histórico)<br>↓<br><b>CONCLUSIÓN</b> (cierro y refuerzo la tesis)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué parte falta?", "q": "Si un texto solo dice \"La Reconquista duró casi 800 años y terminó en 1492 con la toma de Granada\" y \"Por tanto, fue un proceso muy largo\", pero no dice desde el principio qué idea quiere defender, ¿qué parte le falta?", "opts": [{"t": "La tesis", "ok": true}, {"t": "Los argumentos", "ok": false}, {"t": "Los conectores", "ok": false}, {"t": "El título", "ok": false}], "okMsg": "Exacto. Sin una tesis clara al principio, el lector no sabe qué idea estás defendiendo, aunque los datos sean correctos.", "noMsg": "Repasa el esquema: ese texto sí tiene un dato (argumento) y una frase de cierre, pero nunca dice qué idea concreta defiende desde el inicio. Eso es la tesis."}, {"type": "reflect", "kicker": "Tu turno", "h": "Analiza un texto argumentativo real", "body": "Pide a tu profesor o a tu padre/madre el texto argumentativo corto sobre la Reconquista de esta sesión. Léelo con calma, subrayando cada parte con un color distinto.", "prompt": "Lee el texto argumentativo sobre la Reconquista y escribe en tu cuaderno: 1) la <b>tesis</b> con tus propias palabras, 2) los <b>dos argumentos</b> que usa el autor, 3) cómo es la <b>conclusión</b>. Después, en dos líneas, di si a ti el argumento te parece convincente y por qué."}]},
  "p5:Dic:2": {"title": "Escribo mi propio texto argumentativo sobre la Reconquista", "steps": [{"type": "hook", "kicker": "Semana 2 · Diciembre", "h": "Ya sabes identificar un buen argumento. ¿Y si ahora lo construyes tú?", "scenario": "La semana pasada aprendiste a reconocer la tesis, los argumentos y la conclusión en un texto ya escrito. Ahora te toca a ti sentarte con un folio en blanco y defender tu propia postura.", "body": "Escribir bien un texto argumentativo no es solo tener una opinión: es <b>ordenarla</b> con conectores que guíen al lector de una idea a la siguiente. Esta semana vas a escribir un texto de 12 oraciones sobre si la Reconquista fue positiva para España, usando los <b>conectores argumentativos</b> adecuados."}, {"type": "theory", "kicker": "Teoría", "h": "Los conectores: el pegamento de tus ideas", "body": "Los <b>conectores argumentativos</b> son palabras o expresiones que unen tus ideas y muestran cómo se relacionan entre sí. Para empezar a defender tu tesis puedes usar <b>\"en primer lugar\"</b> o <b>\"para empezar\"</b>. Para añadir otro argumento sirve <b>\"además\"</b> o <b>\"asimismo\"</b>. Para mostrar una consecuencia usa <b>\"por lo tanto\"</b> o <b>\"por consiguiente\"</b>. Y si quieres matizar o mostrar el otro lado, usa <b>\"sin embargo\"</b> o <b>\"no obstante\"</b>. Para cerrar tu texto, <b>\"en conclusión\"</b> o <b>\"en definitiva\"</b> avisan al lector de que llega el final.", "diagram": "Empezar → <b>en primer lugar</b><br>Añadir → <b>además, asimismo</b><br>Consecuencia → <b>por lo tanto</b><br>Matizar → <b>sin embargo</b><br>Cerrar → <b>en conclusión</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Elige el conector correcto", "q": "Quieres escribir: \"La Reconquista unificó territorios bajo una misma corona. ___, también provocó siglos de conflicto entre reinos.\" ¿Qué conector encaja mejor en el hueco?", "opts": [{"t": "Sin embargo", "ok": true}, {"t": "Además", "ok": false}, {"t": "En primer lugar", "ok": false}, {"t": "Por ejemplo", "ok": false}], "okMsg": "Correcto. La segunda idea matiza o contrasta con la primera, así que \"sin embargo\" es el conector adecuado.", "noMsg": "Fíjate en que la segunda frase contradice o matiza a la primera (algo positivo, algo problemático). Ese contraste pide un conector como \"sin embargo\"."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe tu texto argumentativo", "body": "Elige tu postura: ¿fue la Reconquista positiva para España, negativa, o tuvo luces y sombras? Sea cual sea tu opinión, defiéndela con datos históricos, no solo con sentimientos.", "prompt": "Escribe un texto argumentativo de exactamente <b>12 oraciones</b> sobre si la Reconquista fue positiva para España. Debe incluir: una tesis clara al principio, al menos tres argumentos con datos históricos, al menos tres conectores argumentativos distintos y una conclusión final que retome tu tesis."}]},
  "p5:Dic:3": {"title": "Puntuación con puntería: corrijo un texto argumentativo", "steps": [{"type": "hook", "kicker": "Semana 3 · Diciembre", "h": "Una coma mal puesta puede cambiar el sentido de todo un argumento", "scenario": "Tu padre ha preparado un texto sobre la Reconquista, pero se le han colado varios errores de puntuación al escribirlo rápido. Algunas frases, sin los puntos y comas en su sitio, casi no se entienden.", "body": "Un texto argumentativo perfecto por dentro (con buena tesis y buenos argumentos) puede fallar si la <b>puntuación</b> está mal, porque el lector se pierde o entiende otra cosa. Esta semana toca ponerse el gorro de corrector."}, {"type": "theory", "kicker": "Teoría", "h": "La puntuación también argumenta", "body": "En un texto argumentativo, el <b>punto</b> separa ideas completas y le da al lector un respiro para asimilar cada argumento. La <b>coma</b> separa elementos de una enumeración (por ejemplo, varios argumentos seguidos) y también aísla los conectores como \"sin embargo,\" o \"por lo tanto,\" cuando van al principio de la frase. Los <b>dos puntos</b> se usan para anunciar una enumeración o una explicación (\"Hay dos motivos: primero... segundo...\"). Olvidar una coma después de un conector, o poner un punto en medio de una idea que aún no ha terminado, puede hacer que el argumento se entienda al revés de lo que querías decir.", "diagram": "<b>Punto</b> → separa ideas completas<br><b>Coma</b> → separa enumeraciones y aísla conectores<br><b>Dos puntos</b> → anuncian una lista o explicación"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Encuentra el error", "q": "¿Cuál de estas frases tiene la puntuación correcta?", "opts": [{"t": "Sin embargo, la unificación trajo también nuevas leyes comunes.", "ok": true}, {"t": "Sin embargo la unificación trajo también, nuevas leyes comunes.", "ok": false}, {"t": "Sin, embargo la unificación trajo también nuevas leyes comunes.", "ok": false}, {"t": "Sin embargo la unificación, trajo también nuevas leyes comunes.", "ok": false}], "okMsg": "Correcto. El conector \"sin embargo\" va seguido de una coma cuando abre la frase, y el resto no necesita comas adicionales.", "noMsg": "Recuerda: la coma va justo después del conector \"sin embargo\" cuando este abre la frase, no en mitad de la oración."}, {"type": "reflect", "kicker": "Tu turno", "h": "Corrige el texto de papá", "body": "Pide a tu padre o profesor el texto con errores de puntuación preparado para esta sesión. Léelo primero entero sin tocar nada, para entender qué quiere decir.", "prompt": "Copia el texto con errores de puntuación en tu cuaderno y corrígelo: añade los puntos, comas y dos puntos que falten y elimina los que sobren. Al final, escribe en una frase qué error se repetía más veces."}]},
  "p5:Dic:4": {"title": "Hablar la verdad en amor: el debate honesto como virtud cristiana", "steps": [{"type": "hook", "kicker": "Semana 4 · Diciembre", "h": "¿Se puede debatir sin dejar de amar al otro?", "scenario": "Después de tres semanas aprendiendo a argumentar, te das cuenta de que a veces, cuando alguien defiende una idea distinta a la tuya, es tentador querer \"ganar\" a cualquier precio, aunque sea exagerando o faltando al respeto.", "body": "La Biblia nos enseña algo distinto en <b>Efesios 4:15</b>: \"hablar la verdad en amor\". Argumentar bien no es solo usar tesis, argumentos y conectores correctamente: es también hacerlo con honestidad y respeto hacia quien piensa diferente."}, {"type": "theory", "kicker": "Teoría", "h": "El versículo de la semana", "body": "\"<i>Siguiendo la verdad en amor, crezcamos en aquel que es la cabeza</i>\" (Efesios 4:15). Este versículo une dos cosas que a veces parecen contrarias: la <b>verdad</b> y el <b>amor</b>. Un cristiano no debe callar la verdad para \"quedar bien\", pero tampoco debe usarla como un arma para humillar a otro. Aplicado a lo que has aprendido este mes: un buen texto argumentativo defiende una tesis con datos reales (verdad), pero lo hace con respeto hacia quien piensa distinto (amor). Esto es justo lo contrario de discutir a gritos o de inventar datos falsos para ganar una discusión.", "diagram": "<b>VERDAD</b> (datos reales, argumentos honestos)<br>+<br><b>AMOR</b> (respeto por quien piensa distinto)<br>=<br><b>Debate honesto</b> (Efesios 4:15)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué significa \"hablar la verdad en amor\"?", "q": "Según Efesios 4:15, ¿cuál de estas actitudes refleja mejor lo que significa \"hablar la verdad en amor\" al defender una postura sobre la Reconquista?", "opts": [{"t": "Defender mi tesis con datos reales, escuchando y respetando a quien opina distinto", "ok": true}, {"t": "Callar mi opinión para no discutir con nadie", "ok": false}, {"t": "Exagerar los datos para que mi argumento parezca más fuerte", "ok": false}, {"t": "Convencer al otro gritando más fuerte que él", "ok": false}], "okMsg": "Exacto. Hablar la verdad en amor es unir honestidad (datos reales) y respeto (escuchar al otro), justo lo que buscas en un buen texto argumentativo.", "noMsg": "Piensa que el versículo une dos cosas: decir la verdad (no exagerar ni callar) y hacerlo con amor (respetando al otro, sin gritar ni humillar)."}, {"type": "reflect", "kicker": "Entregable del mes", "h": "El debate honesto como virtud cristiana", "body": "Ha llegado el momento de reunir todo lo aprendido este mes: estructura, conectores, puntuación correcta y la actitud de Efesios 4:15.", "prompt": "Escribe la versión final de tu texto argumentativo sobre si la Reconquista fue positiva para España (puedes partir del que escribiste en la semana 2, revisando su puntuación). Añade al final un párrafo breve explicando cómo has intentado \"hablar la verdad en amor\": qué datos reales has usado y cómo has tratado con respeto la opinión contraria a la tuya."}]},
  "p5:Feb:1": {"title": "Cuatro viajes, un océano: la ruta de Colón", "steps": [{"type": "hook", "kicker": "Semana 1 · Febrero", "h": "¿Sabías que Colón cruzó el Atlántico no una, sino cuatro veces?", "scenario": "Cuando pensamos en Colón, casi siempre imaginamos solo el viaje de 1492. Pero aquel fue solo el primero de cuatro expediciones distintas, cada una hacia lugares diferentes.", "body": "Este mes vamos a estudiar <b>el viaje de Colón</b>: sus cuatro travesías y los territorios que exploró, el encuentro entre dos mundos que aquello provocó, y la figura de <b>Bartolomé de las Casas</b>, que defendió con argumentos bíblicos la dignidad de los pueblos indígenas."}, {"type": "theory", "kicker": "Teoría", "h": "Los cuatro viajes de Colón", "body": "Colón realizó <b>cuatro viajes</b> entre 1492 y 1504. En el <b>primero</b> (1492) llegó a las islas del Caribe, creyendo haber alcanzado Asia. En el <b>segundo</b> (1493) exploró las Antillas Menores y estableció los primeros asentamientos permanentes. En el <b>tercero</b> (1498) llegó por primera vez a <b>Tierra Firme</b>, es decir, al continente americano, tocando la actual Venezuela y la isla de Trinidad. En el <b>cuarto</b> (1502) recorrió la costa de lo que hoy son Costa Rica y Panamá, buscando un paso hacia el otro océano que nunca encontró.", "diagram": "<b>1er viaje (1492)</b> → islas del Caribe<br><b>2º viaje (1493)</b> → Antillas Menores<br><b>3er viaje (1498)</b> → Tierra Firme (Venezuela/Trinidad)<br><b>4º viaje (1502)</b> → Costa Rica y Panamá"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿En qué viaje llegó al continente?", "q": "¿En cuál de sus cuatro viajes pisó Colón por primera vez el continente americano (Tierra Firme)?", "opts": [{"t": "En el tercer viaje (1498)", "ok": true}, {"t": "En el primer viaje (1492)", "ok": false}, {"t": "En el segundo viaje (1493)", "ok": false}, {"t": "En el cuarto viaje (1502)", "ok": false}], "okMsg": "Correcto. En 1492 y 1493 Colón solo llegó a islas; fue en 1498, en su tercer viaje, cuando alcanzó por primera vez el continente, cerca de la actual Venezuela.", "noMsg": "Repasa el orden: los dos primeros viajes fueron a islas del Caribe. El continente (Tierra Firme) se alcanzó por primera vez en el tercer viaje, en 1498."}, {"type": "reflect", "kicker": "Tu turno", "h": "Dibuja el mapa de los cuatro viajes", "body": "Consigue o dibuja un mapa sencillo del océano Atlántico con España, el Caribe y la costa americana.", "prompt": "Traza sobre tu mapa las rutas de los cuatro viajes de Colón, usando un <b>color diferente para cada viaje</b>. Añade una pequeña leyenda que indique qué color corresponde a cada viaje y el año en que ocurrió. Debajo del mapa, escribe una frase por viaje explicando a qué territorio llegó."}]},
  "p5:Feb:2": {"title": "El diario de a bordo: leer entre líneas el 12 de octubre de 1492", "steps": [{"type": "hook", "kicker": "Semana 2 · Febrero", "h": "¿Cómo describió Colón el primer encuentro con un pueblo desconocido?", "scenario": "Imagina llevar semanas navegando sin ver tierra, y de repente, el 12 de octubre de 1492, avistar una costa habitada por gente que nunca antes habías visto ni imaginado.", "body": "El <b>diario de a bordo</b> de Colón es una fuente histórica de primera mano: nos cuenta, con sus propias palabras, cómo vivió aquel primer encuentro. Esta semana vamos a leer un fragmento y analizar con cuidado su <b>tono</b>."}, {"type": "theory", "kicker": "Teoría", "h": "Leer un documento histórico con ojo crítico", "body": "Un <b>diario</b> escrito en el momento de los hechos es una fuente muy valiosa porque refleja las primeras impresiones de quien lo escribe, sin el paso del tiempo. Pero también hay que leerlo con cuidado: Colón escribía desde su propio punto de vista, con sus propios intereses (buscaba impresionar a los Reyes Católicos) y sus propias creencias sobre el mundo. Analizar el <b>tono</b> de un texto significa fijarse en si el autor se muestra admirado, sorprendido, calculador, respetuoso o interesado, y distinguir entre lo que describe (los hechos) y cómo lo valora (su opinión).", "diagram": "<b>Fuente primaria</b> → escrita en el momento de los hechos<br><b>Hechos</b> → lo que describe (personas, tierras, costumbres)<br><b>Tono</b> → cómo lo valora (admiración, interés, cálculo)"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Hechos y valoración", "q": "Cuando analizas el fragmento del diario de Colón del 12 de octubre de 1492, ¿qué debes distinguir con más cuidado?", "opts": [{"t": "Los hechos que describe frente a las opiniones o el tono con que los cuenta", "ok": true}, {"t": "Solo la fecha exacta en que fue escrito", "ok": false}, {"t": "El número de páginas que ocupa el diario", "ok": false}, {"t": "El idioma en el que está redactado", "ok": false}], "okMsg": "Correcto. Un buen análisis histórico separa lo que el autor describe (los hechos) de cómo lo valora (su tono y sus opiniones).", "noMsg": "Piensa en qué distingue a un buen análisis de fuentes históricas: no basta con la fecha o el idioma, hay que separar los hechos de la valoración personal del autor."}, {"type": "reflect", "kicker": "Tu turno", "h": "Analiza el tono del fragmento", "body": "Lee con calma el fragmento del diario de Colón del 12 de octubre de 1492 que te entreguen en la sesión.", "prompt": "Después de leer el fragmento, escribe en tu cuaderno: 1) tres <b>hechos</b> concretos que Colón describe ese día, 2) dos palabras o frases que muestren el <b>tono</b> con el que escribe (admiración, sorpresa, interés...), y 3) tu propia reflexión sobre cómo crees que se sintieron las personas que Colón describió al ver llegar aquellos barcos."}]},
  "p5:Feb:3": {"title": "Bartolomé de las Casas: una voz bíblica en defensa de la dignidad", "steps": [{"type": "hook", "kicker": "Semana 3 · Febrero", "h": "¿Puede una sola persona levantar la voz por miles?", "scenario": "Tras el encuentro entre los dos mundos, muchos indígenas fueron tratados con enorme injusticia. En medio de aquello, un fraile español, Bartolomé de las Casas, decidió defenderlos ante el propio rey, usando argumentos tomados de la Biblia.", "body": "Esta semana conocerás a <b>Bartolomé de las Casas</b> y los <b>argumentos bíblicos</b> que empleó para defender la dignidad de los pueblos indígenas, en un momento en que muchos no la reconocían."}, {"type": "theory", "kicker": "Teoría", "h": "Tres argumentos bíblicos de Bartolomé de las Casas", "body": "Bartolomé de las Casas fue un fraile que, tras ver el maltrato hacia los indígenas en América, dedicó su vida a defenderlos. Usó, entre otros, tres argumentos con base bíblica. Primero, que todo ser humano está hecho <b>a imagen de Dios</b> (Génesis 1:27), por lo que ningún pueblo vale menos que otro. Segundo, que Dios <b>ha hecho de una sangre a todas las naciones</b> (Hechos 17:26), es decir, que ante Dios no existen pueblos superiores ni inferiores. Tercero, el mandamiento de <b>amar al prójimo como a uno mismo</b> (Marcos 12:31), que no admite excepciones según el origen o la cultura de la persona.", "diagram": "<b>Génesis 1:27</b> → todos hechos a imagen de Dios<br><b>Hechos 17:26</b> → todas las naciones vienen de un mismo origen<br><b>Marcos 12:31</b> → amar al prójimo sin excepción"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "¿Qué defendía de las Casas?", "q": "¿Cuál era la idea central que Bartolomé de las Casas defendía usando la Biblia?", "opts": [{"t": "Que todos los seres humanos, sin importar su origen, tienen la misma dignidad ante Dios", "ok": true}, {"t": "Que solo algunos pueblos merecían ser tratados con respeto", "ok": false}, {"t": "Que la Biblia no tenía nada que decir sobre cómo tratar a otras personas", "ok": false}, {"t": "Que los territorios americanos no debían explorarse nunca", "ok": false}], "okMsg": "Correcto. De las Casas usó la Biblia precisamente para defender que todo ser humano, sin excepción, tiene la misma dignidad por ser creado a imagen de Dios.", "noMsg": "Repasa los tres argumentos: todos apuntan en la misma dirección, que ningún ser humano vale menos que otro ante Dios, sea cual sea su origen."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe los tres argumentos con tus palabras", "body": "Vuelve a leer los tres argumentos bíblicos de Bartolomé de las Casas antes de escribir tu respuesta.", "prompt": "Escribe en tu cuaderno los <b>tres argumentos bíblicos</b> que usó Bartolomé de las Casas para defender la dignidad de los indígenas, explicando cada uno con tus propias palabras y citando el versículo en el que se apoya. Después, añade una frase sobre qué grupo de personas crees que hoy necesitaría que alguien defendiera su dignidad como hizo de las Casas."}]},
  "p5:Feb:4": {"title": "A todas las naciones: el proyecto \"El encuentro de dos mundos\"", "steps": [{"type": "hook", "kicker": "Semana 4 · Febrero", "h": "¿Qué significa llevar un mensaje a \"todas las naciones\"?", "scenario": "Has trazado las rutas de Colón, has leído su diario y has conocido cómo Bartolomé de las Casas defendió a los indígenas con la Biblia. Ahora toca unir todo lo aprendido en un proyecto final.", "body": "Jesús dijo en <b>Mateo 28:19</b>: \"Id, y haced discípulos a todas las naciones\". Este versículo no distingue entre pueblos: <b>todas</b> las naciones importan por igual. Es el mismo principio que defendió Bartolomé de las Casas siglos después."}, {"type": "theory", "kicker": "Teoría", "h": "El versículo de la semana", "body": "\"<i>Id, y haced discípulos a todas las naciones</i>\" (Mateo 28:19). Cuando Jesús pronunció estas palabras, estaba diciendo algo muy fuerte para su época: el mensaje del evangelio no era solo para un pueblo, sino para <b>todas las naciones</b>, sin excepción. Esto significa que ningún pueblo es más importante que otro a los ojos de Dios. Por eso, cuando estudiamos el encuentro entre Europa y América, es importante recordar que aquellos pueblos indígenas, con sus propias culturas e historias, tenían la misma dignidad que cualquier otro ser humano: la misma dignidad que defendió Bartolomé de las Casas con la Biblia en la mano.", "diagram": "<b>Mateo 28:19</b> → \"a todas las naciones\"<br>↓<br>Ninguna nación vale menos que otra<br>↓<br>Misma idea que defendió <b>Bartolomé de las Casas</b>"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Une el versículo con la historia", "q": "¿Qué tienen en común el mensaje de Mateo 28:19 (\"a todas las naciones\") y la defensa que hizo Bartolomé de las Casas de los indígenas?", "opts": [{"t": "Ambos afirman que ningún pueblo vale menos que otro ante Dios", "ok": true}, {"t": "Ambos dicen que solo un pueblo concreto merece respeto", "ok": false}, {"t": "Ninguno de los dos tiene relación con la dignidad humana", "ok": false}, {"t": "Ambos hablan únicamente de rutas de navegación", "ok": false}], "okMsg": "Correcto. Tanto el versículo como la defensa de de las Casas parten de la misma idea: todas las naciones y personas tienen igual dignidad.", "noMsg": "Piensa en el punto en común: el versículo habla de \"todas las naciones\" sin distinción, exactamente lo que defendió de las Casas para los indígenas."}, {"type": "reflect", "kicker": "Entregable del mes", "h": "Proyecto \"El encuentro de dos mundos\"", "body": "Ha llegado el momento de reunir en un solo proyecto todo lo trabajado este mes: el mapa de los viajes, el análisis del diario y los argumentos de Bartolomé de las Casas.", "prompt": "Elabora tu proyecto final \"El encuentro de dos mundos\" con tres partes: 1) el mapa coloreado de los cuatro viajes de Colón con una breve explicación de cada uno, 2) tu análisis de hechos y tono del fragmento del diario del 12 de octubre de 1492, y 3) los tres argumentos bíblicos de Bartolomé de las Casas. Cierra el proyecto con un párrafo final explicando, con tus propias palabras, qué significa para ti que Dios envíe su mensaje \"a todas las naciones\" (Mateo 28:19) cuando piensas en el encuentro entre Europa y América."}]},
  "p5:Mar:1": {"title": "El Romancero: voces del pueblo español", "steps": [{"type": "hook", "kicker": "Antes de internet, así se contaban historias...", "h": "¿Cómo se contaban las noticias hace 600 años?", "scenario": "Imagina un pueblo sin televisión ni radio. Un juglar llega a la plaza, saca su instrumento y empieza a cantar una historia de amor, guerra o traición.", "body": "Eso eran los <b>romances</b>: poemas breves, anónimos, que se transmitían de boca en boca y se cantaban en plazas y caminos. Hoy los seguimos leyendo porque cuentan la vida, los valores y los miedos de una época."}, {"type": "theory", "kicker": "El Romancero español", "h": "¿Qué es un romance?", "body": "El <b>Romancero</b> es el conjunto de romances que se compusieron en España desde la Edad Media. Sus temas más frecuentes son: <b>históricos</b> (batallas, reyes, la Reconquista), <b>fronterizos</b> (la vida en la frontera con el reino nazarí), <b>líricos</b> (amor, nostalgia) y <b>novelescos</b> (aventuras inventadas). Su ritmo es muy reconocible: versos de <b>8 sílabas</b> con rima asonante solo en los versos pares.", "diagram": "ROMANCE<br><b>Autor:</b> anónimo, popular<br><b>Verso:</b> 8 sílabas (octosílabo)<br><b>Rima:</b> asonante en versos pares<br><b>Temas:</b> históricos · fronterizos · líricos · novelescos"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Sobre el Romancero", "q": "¿Cuál de estas características es típica del romance español?", "opts": [{"t": "Versos de 8 sílabas con rima asonante en los pares", "ok": true}, {"t": "Siempre tiene autor conocido y firmado", "ok": false}, {"t": "Solo se escribía, nunca se cantaba", "ok": false}, {"t": "Trata exclusivamente temas religiosos", "ok": false}], "okMsg": "¡Exacto! El octosílabo y la rima asonante en los versos pares son la marca de la casa del romance.", "noMsg": "Repasa: el romance es anónimo, se cantaba, y su métrica es de 8 sílabas con rima asonante en los pares."}, {"type": "reflect", "kicker": "Tu turno", "h": "Lee, escucha, analiza", "body": "Busca (con ayuda de un adulto) o pide en clase el texto de dos romances populares españoles, por ejemplo 'Romance del conde Arnaldos' y 'Romance de Abenámar'. Léelos en voz alta, como haría un juglar.", "prompt": "Escribe el título de los dos romances que has leído y, para cada uno, anota: 1) el tema principal (amor, guerra, aventura...), 2) una frase o verso que te haya llamado la atención, 3) si notas algún ritmo especial al leerlo en voz alta."}]},
  "p5:Mar:2": {"title": "Fray Luis y el deseo de una vida tranquila", "steps": [{"type": "hook", "kicker": "¿Alguna vez has querido escapar del ruido?", "h": "¿Qué buscaba un poeta hace 450 años?", "scenario": "Fray Luis de León era catedrático en Salamanca, un hombre ocupado, rodeado de discusiones y hasta encarcelado injustamente durante años.", "body": "A pesar de (o precisamente por) esa vida agitada, escribió uno de los poemas más serenos de la literatura española: la <b>'Oda a la vida retirada'</b>. En ella imagina una existencia alejada del ruido, la ambición y la envidia, en contacto con la naturaleza y con uno mismo."}, {"type": "theory", "kicker": "Lírica del Siglo de Oro", "h": "Garcilaso y fray Luis: dos voces, un mismo ideal", "body": "En el Siglo de Oro español destacan dos grandes poetas líricos. <b>Garcilaso de la Vega</b> introdujo en España la métrica italiana (el endecasílabo, de 11 sílabas) y escribió sobre el amor y la naturaleza. <b>Fray Luis de León</b>, algo posterior, buscó en sus poemas la paz interior, el ideal del 'beatus ille' (la dicha del que vive alejado del mundanal ruido). Ambos comparten el gusto por la naturaleza como espejo del alma.", "diagram": "SIGLO DE ORO - LÍRICA<br><b>Garcilaso de la Vega:</b> amor, naturaleza, endecasílabo<br><b>Fray Luis de León:</b> paz interior, vida retirada, serenidad<br><b>Tema común:</b> la naturaleza como refugio y símbolo"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Sobre fray Luis de León", "q": "¿Qué busca el poeta en la 'Oda a la vida retirada'?", "opts": [{"t": "Alejarse del ruido y la ambición para vivir en paz con la naturaleza", "ok": true}, {"t": "Ganar fama y riquezas en la corte del rey", "ok": false}, {"t": "Contar una batalla entre cristianos y musulmanes", "ok": false}, {"t": "Burlarse de la vida en el campo", "ok": false}], "okMsg": "Correcto. Fray Luis idealiza la vida sencilla y tranquila, lejos del bullicio de la ciudad y la corte.", "noMsg": "El poema habla de huir del ruido y la ambición para encontrar sosiego en la naturaleza; repásalo."}, {"type": "reflect", "kicker": "Tu turno", "h": "Un rincón de paz", "body": "Lee (o pide que te lean) el fragmento de la 'Oda a la vida retirada' de fray Luis de León que os han entregado en la sesión.", "prompt": "Responde por escrito: ¿qué cosas rechaza el poeta de la vida en la ciudad? ¿qué elementos de la naturaleza aparecen en el fragmento? Después dibuja o describe con tus palabras cómo sería tu propio 'rincón de paz' ideal."}]},
  "p5:Mar:3": {"title": "Contar sílabas, encontrar la rima", "steps": [{"type": "hook", "kicker": "Los poemas también tienen matemáticas", "h": "¿Sabías que los poetas cuentan sílabas como si fueran ladrillos?", "scenario": "Cuando fray Luis o el autor anónimo de un romance escribían, no colocaban las palabras al azar: medían cada verso con precisión, casi como un arquitecto mide una pared.", "body": "Esa medida se llama <b>métrica</b>, y conocerla te permite entender por qué un poema 'suena bien' al leerlo en voz alta."}, {"type": "theory", "kicker": "Métrica básica", "h": "Verso, estrofa y rima", "body": "Un <b>verso</b> es cada línea de un poema. Un conjunto de versos agrupados forma una <b>estrofa</b>. La <b>rima</b> es la coincidencia de sonidos al final de cada verso, a partir de la última vocal acentuada: puede ser <b>consonante</b> (coinciden vocales y consonantes: 'cielo' - 'anhelo') o <b>asonante</b> (coinciden solo las vocales: 'cielo' - 'espejo'). Para contar sílabas se separan las palabras en sonidos y se aplican reglas como la <b>sinalefa</b> (unir la vocal final de una palabra con la vocal inicial de la siguiente).", "diagram": "MÉTRICA BÁSICA<br><b>Verso:</b> una línea del poema<br><b>Estrofa:</b> grupo de versos<br><b>Rima consonante:</b> coinciden vocales + consonantes<br><b>Rima asonante:</b> coinciden solo las vocales"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Sobre la métrica", "q": "¿Qué tipo de rima tienen 'ventana' y 'mañana'?", "opts": [{"t": "Rima consonante, porque coinciden vocales y consonantes desde la última vocal acentuada", "ok": true}, {"t": "Rima asonante, porque solo coinciden las vocales", "ok": false}, {"t": "No riman entre sí", "ok": false}, {"t": "Es una sinalefa", "ok": false}], "okMsg": "¡Bien! 'Ventana' y 'mañana' comparten el sonido -ana completo (vocales y consonantes), por eso es rima consonante.", "noMsg": "Fíjate: si coinciden vocales Y consonantes desde la última sílaba acentuada, la rima es consonante."}, {"type": "reflect", "kicker": "Tu turno", "h": "Detective de la rima", "body": "Coge uno de los romances que leíste en la sesión 1 (o el que te entregue tu profesor).", "prompt": "Copia sus versos y, en cada uno, cuenta las sílabas al final de la línea; marca con un color los versos pares (2º, 4º, 6º...) y señala qué sonidos se repiten para formar la rima asonante."}]},
  "p5:Mar:4": {"title": "Mi propio romance: la Historia en verso", "steps": [{"type": "hook", "kicker": "Un versículo para inspirar la pluma", "h": "¿Puedes tú también ser cronista en verso?", "scenario": "Durante siglos, romances anónimos contaron batallas, descubrimientos y hazañas de la historia de España. Ahora te toca a ti convertirte en ese narrador.", "body": "Antes de escribir, recuerda las palabras del Salmo 19:14: <b>'Sean gratos los dichos de mi boca y la meditación de mi corazón delante de ti.'</b> Igual que el salmista cuidaba lo que decía y pensaba, tú puedes poner cuidado y verdad en cada verso que escribas."}, {"type": "theory", "kicker": "Repaso final", "h": "Todo lo que ya sabes sobre el romance", "body": "Recuerda: el romance tiene versos de <b>8 sílabas</b>, rima <b>asonante</b> en los versos pares (los impares quedan libres), y suele narrar un <b>hecho histórico, legendario o sentimental</b>. Elige un evento histórico español que te guste: el Descubrimiento de América, la Reconquista, la vida de un rey o una batalla conocida.", "diagram": "MI ROMANCE<br>8 versos · octosílabos<br>Rima asonante en pares (2º, 4º, 6º, 8º)<br>Tema: un hecho histórico español<br>Actitud: cuidar 'los dichos de mi boca' (Sal 19:14)"}, {"type": "quiz", "kicker": "Última comprobación", "h": "Antes de escribir", "q": "Según lo aprendido, ¿cuántos versos debe tener tu romance y qué rima deben llevar los pares?", "opts": [{"t": "8 versos octosílabos, con rima asonante en los versos pares", "ok": true}, {"t": "4 versos endecasílabos, sin ninguna rima", "ok": false}, {"t": "8 versos con rima consonante en todos los versos", "ok": false}, {"t": "12 versos libres sin métrica fija", "ok": false}], "okMsg": "Perfecto, esa es la estructura que vas a seguir para tu propio romance.", "noMsg": "Recuerda la estructura pedida: 8 versos octosílabos con rima asonante en los pares."}, {"type": "reflect", "kicker": "Tu turno", "h": "Escribe tu romance", "body": "Elige un evento histórico español (por ejemplo, un descubrimiento, una batalla o la vida de un personaje) y conviértelo en un romance de 8 versos, cuidando la métrica y la rima que has aprendido.", "prompt": "Escribe tu romance de 8 versos octosílabos con rima asonante en los versos pares sobre un evento histórico español. Antes de entregarlo, léelo en voz alta y comprueba, como pide el Salmo 19:14, que sus palabras 'sean gratas' y digan la verdad sobre lo que cuentas. Este será tu entregable: el Portfolio 'Poesía española clásica'."}]},
  "p5:Abr:1": {"title": "La Inquisición: hechos y miradas distintas", "steps": [{"type": "hook", "kicker": "Un mismo hecho, historias distintas", "h": "¿Puede la Historia contarse de más de una manera?", "scenario": "En el siglo XVI, España vivía una época de gran esplendor artístico y religioso, pero también existía un tribunal, la Inquisición, encargado de vigilar la fe de los cristianos.", "body": "Estudiar la <b>Inquisición</b> nos obliga a separar dos cosas: los <b>hechos</b> (lo que ocurrió, documentado) y las <b>interpretaciones</b> (cómo se valora hoy lo que ocurrió). Un buen historiador aprende a distinguir ambas cosas."}, {"type": "theory", "kicker": "Contexto histórico", "h": "¿Qué fue la Inquisición?", "body": "La <b>Inquisición española</b> fue un tribunal creado en 1478 por los Reyes Católicos para vigilar la ortodoxia religiosa en un reino que buscaba la unidad tras siglos de convivencia entre cristianos, judíos y musulmanes. Entre sus <b>hechos</b> documentados están los procesos judiciales, el uso de la tortura en algunos casos y las condenas, incluida la pena de muerte. Entre las <b>interpretaciones</b> actuales, unos historiadores destacan su papel en el control social y político, mientras otros señalan que su dureza real fue en ocasiones exagerada por la propaganda de otros países rivales de España (la llamada 'leyenda negra'). Ambas miradas conviven en el debate histórico.", "diagram": "LA INQUISICIÓN<br><b>Hechos:</b> tribunal creado en 1478 · procesos judiciales · condenas<br><b>Interpretación 1:</b> instrumento de control y represión<br><b>Interpretación 2:</b> su dureza fue exagerada por la 'leyenda negra'<br>Un mismo hecho admite varias miradas"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Hechos e interpretaciones", "q": "¿Qué diferencia hay entre un 'hecho' histórico y una 'interpretación'?", "opts": [{"t": "El hecho es lo documentado y ocurrido; la interpretación es cómo se valora hoy", "ok": true}, {"t": "Son exactamente lo mismo, no hay diferencia", "ok": false}, {"t": "El hecho es siempre una opinión personal", "ok": false}, {"t": "La interpretación es un dato que nadie puede discutir", "ok": false}], "okMsg": "Exacto. Distinguir hechos de interpretaciones es una de las claves del pensamiento histórico crítico.", "noMsg": "Repasa: el hecho es lo que sucedió y está documentado; la interpretación es la valoración que se hace de ese hecho."}, {"type": "reflect", "kicker": "Tu turno", "h": "Hechos e interpretaciones, cara a cara", "body": "Lee el texto sobre la Inquisición que te ha entregado tu profesor o tu familia en esta sesión.", "prompt": "Elabora una tabla en tu cuaderno con dos columnas: 'Hechos' y 'Interpretaciones'. Anota 3 hechos objetivos del texto (fechas, instituciones, acciones documentadas) y 3 interpretaciones distintas que hayas encontrado o que se te ocurran sobre esos hechos."}]},
  "p5:Abr:2": {"title": "Conciencia y autoridad: un debate para pensar en familia", "steps": [{"type": "hook", "kicker": "¿Y si la ley te pide algo que tu conciencia rechaza?", "h": "¿Puede un Estado imponer una fe a sus ciudadanos?", "scenario": "En el Siglo de Oro, España se definía como un reino católico, y las leyes exigían unidad religiosa. Hoy, en cambio, la mayoría de los países reconocen la libertad de conciencia y de religión como un derecho.", "body": "Esta tensión entre <b>autoridad del Estado</b> y <b>libertad de conciencia</b> no es solo cosa del pasado: sigue siendo un tema de debate en el mundo actual. Por eso, esta semana el reto no es memorizar una respuesta, sino aprender a <b>argumentar</b> con respeto distintos puntos de vista."}, {"type": "theory", "kicker": "Para preparar el debate", "h": "Argumentos a favor y en contra", "body": "Algunos argumentan que un Estado necesita <b>cohesión y unidad</b> para mantener la paz social, y que en el siglo XVI se pensaba que la unidad religiosa era parte de esa cohesión. Otros argumentan que la <b>conciencia personal</b> es algo tan íntimo que ningún poder humano debería obligar a creer o dejar de creer algo por la fuerza. La Biblia misma, en Hechos 5:29, recoge un principio importante: cuando la autoridad humana exige algo contrario a lo que Dios manda, los primeros cristianos eligieron obedecer primero a Dios, aun arriesgando su seguridad.", "diagram": "DEBATE: ESTADO Y CONCIENCIA<br><b>A favor de la unidad impuesta:</b> cohesión social, orden<br><b>A favor de la libertad de conciencia:</b> respeto a la persona, fe voluntaria<br><b>Principio bíblico (Hech 5:29):</b> obedecer a Dios antes que a los hombres, cuando hay conflicto"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Sobre el debate", "q": "Según Hechos 5:29, ¿qué hicieron los primeros cristianos cuando la autoridad les prohibió hablar de su fe?", "opts": [{"t": "Eligieron obedecer a Dios antes que a los hombres, aun con riesgo", "ok": true}, {"t": "Obedecieron sin más a la autoridad y dejaron de creer", "ok": false}, {"t": "Se escondieron para siempre y no volvieron a hablar del tema", "ok": false}, {"t": "Pidieron permiso al Emperador romano", "ok": false}], "okMsg": "Correcto. Hechos 5:29 muestra que, ante un conflicto de conciencia, ellos priorizaron obedecer a Dios.", "noMsg": "Recuerda: el versículo dice que 'es necesario obedecer a Dios antes que a los hombres'; por eso no dejaron de hablar de su fe."}, {"type": "reflect", "kicker": "Tu turno", "h": "Debate en casa", "body": "Organiza con tu familia un pequeño debate sobre la pregunta: ¿puede un Estado cristiano actuar contra la conciencia de sus ciudadanos? Escucha los distintos argumentos con respeto, aunque no estés de acuerdo con todos.", "prompt": "Escribe un resumen del debate familiar: anota al menos un argumento a favor de la unidad impuesta por el Estado, un argumento a favor de la libertad de conciencia, y tu propia conclusión razonada, explicando por qué piensas así."}]},
  "p5:Abr:3": {"title": "El Greco: el arte que mira al cielo", "steps": [{"type": "hook", "kicker": "Un cuadro que separa la tierra del cielo", "h": "¿Puede un cuadro contar una historia de fe?", "scenario": "En Toledo, a finales del siglo XVI, un pintor de origen griego llamado Doménikos Theotokópoulos, conocido como 'El Greco', recibió el encargo de pintar el entierro de un noble piadoso, el Conde de Orgaz.", "body": "El resultado fue una de las obras maestras del arte español: <b>'El entierro del Conde de Orgaz'</b>, un cuadro que no solo representa un funeral, sino toda una visión del mundo del Siglo de Oro."}, {"type": "theory", "kicker": "El arte como reflejo de la fe", "h": "Analiza 'El entierro del Conde de Orgaz'", "body": "El cuadro está dividido en <b>dos planos</b>: en la parte inferior, terrenal, aparecen nobles y clérigos vestidos con gran realismo, presenciando cómo San Esteban y San Agustín bajan milagrosamente del cielo para enterrar al Conde con sus propias manos. En la parte superior, celestial, con colores y formas más alargadas y luminosas, el alma del Conde asciende hacia Cristo, rodeado de ángeles y santos. Esta composición refleja una idea central del arte del S. XVI-XVII: la vida terrenal y la vida eterna están conectadas, y las buenas obras (el Conde fue conocido por su piedad) tienen recompensa espiritual.", "diagram": "EL ENTIERRO DEL CONDE DE ORGAZ (El Greco)<br><b>Plano terrenal (abajo):</b> realismo, nobles, clérigos, el milagro del entierro<br><b>Plano celestial (arriba):</b> colores luminosos, formas alargadas, el alma asciende<br><b>Mensaje:</b> la fe y las buenas obras unen la tierra con el cielo"}, {"type": "quiz", "kicker": "Comprueba lo que sabes", "h": "Sobre El Greco", "q": "¿Cómo está organizado 'El entierro del Conde de Orgaz'?", "opts": [{"t": "En dos planos: uno terrenal y realista abajo, y otro celestial y luminoso arriba", "ok": true}, {"t": "En un único plano, todo pintado con el mismo estilo realista", "ok": false}, {"t": "Solo representa ángeles, sin ninguna persona real", "ok": false}, {"t": "Es un paisaje sin ninguna figura humana", "ok": false}], "okMsg": "¡Muy bien! Esa división entre el plano terrenal y el celestial es la clave de la composición del cuadro.", "noMsg": "Recuerda: el cuadro se divide en un plano terrenal (realista, abajo) y un plano celestial (luminoso, arriba)."}, {"type": "reflect", "kicker": "Tu turno", "h": "Mira, describe, interpreta", "body": "Observa con atención una reproducción de 'El entierro del Conde de Orgaz' de El Greco (puedes buscarla con ayuda de un adulto o usar la que te entreguen en clase).", "prompt": "Describe por escrito qué ves en la parte de abajo del cuadro y qué ves en la parte de arriba. Después explica con tus palabras qué mensaje crees que El Greco quería transmitir sobre la fe y la vida eterna."}]},
  "p5:Abr:4": {"title": "Grandeza y sombras: cerrando el Siglo de Oro", "steps": [{"type": "hook", "kicker": "Una frase que resume todo un dilema", "h": "¿Qué pesa más: obedecer a los hombres o a Dios?", "scenario": "Hemos visto la grandeza artística y espiritual del Siglo de Oro, pero también sus sombras, como los excesos de la Inquisición. Esta última sesión reúne todo lo aprendido en una sola pregunta de fondo.", "body": "Los primeros cristianos, siglos antes del Siglo de Oro, ya se habían enfrentado a esta disyuntiva y respondieron con una frase que ha inspirado a muchos a lo largo de la historia: <b>'Es necesario obedecer a Dios antes que a los hombres'</b> (Hechos 5:29)."}, {"type": "theory", "kicker": "Cerrando el tema", "h": "Grandeza y sombras del Siglo de Oro", "body": "El Siglo de Oro español fue un tiempo de <b>grandeza</b>: grandes pintores como El Greco, grandes escritores, una fe profunda que inspiró obras de arte inmortales. Pero también tuvo <b>sombras</b>: la Inquisición y sus excesos, la falta de libertad de conciencia para muchas personas. Aprender historia con honestidad significa poder reconocer ambas caras a la vez, sin negar ni exagerar ninguna. El principio de Hechos 5:29 nos recuerda que la fe verdadera no se impone por la fuerza, sino que nace de una conciencia libre que decide, incluso a veces en contra de la autoridad humana, obedecer a Dios.", "diagram": "SIGLO DE ORO: GRANDEZA Y SOMBRAS<br><b>Grandeza:</b> arte (El Greco), literatura, fe profunda<br><b>Sombras:</b> Inquisición, falta de libertad de conciencia<br><b>Principio guía (Hech 5:29):</b> 'Es necesario obedecer a Dios antes que a los hombres'"}, {"type": "quiz", "kicker": "Última comprobación", "h": "Cierre del tema", "q": "¿Qué actitud demuestra un análisis histórico honesto del Siglo de Oro, según lo trabajado estas semanas?", "opts": [{"t": "Reconocer tanto la grandeza artística y espiritual como las sombras, sin negar ni exagerar ninguna", "ok": true}, {"t": "Solo hablar de los logros artísticos y olvidar todo lo demás", "ok": false}, {"t": "Solo hablar de la Inquisición y negar cualquier logro cultural", "ok": false}, {"t": "Evitar el tema porque es demasiado antiguo para importar hoy", "ok": false}], "okMsg": "Así es. La honestidad histórica exige mirar la grandeza y las sombras de una época a la vez.", "noMsg": "Recuerda: un buen análisis histórico reconoce tanto los logros como los errores de una época, sin negar ninguno."}, {"type": "reflect", "kicker": "Tu turno", "h": "Tu trabajo final: grandeza y sombras", "body": "Es momento de reunir todo lo aprendido sobre el Siglo de Oro en tu entregable final: el trabajo 'El Siglo de Oro: grandeza y sombras'.", "prompt": "Elabora tu trabajo final incluyendo: 1) un apartado de 'Grandeza' (menciona el arte, por ejemplo El Greco, y algún otro logro cultural), 2) un apartado de 'Sombras' (menciona la Inquisición y sus interpretaciones), 3) una reflexión personal final que incluya el versículo de Hechos 5:29 y lo que significa para ti la libertad de conciencia."}]},
  "p5:May:1": {"title": "¿Qué produce España?", "steps": [{"type": "hook", "kicker": "Economía en acción", "h": "¿De dónde viene lo que comes y usas cada día?", "scenario": "Imagina un desayuno: pan hecho con trigo cultivado en Castilla, leche de una granja gallega, y un móvil fabricado en una gran fábrica.", "body": "Todo lo que consumimos pasa por <b>tres sectores económicos</b> antes de llegar a nuestras manos. Esta semana descubrirás cómo se organiza la economía de España región por región."}, {"type": "theory", "kicker": "Los tres sectores", "h": "Primario, secundario y terciario", "body": "El <b>sector primario</b> obtiene materias primas directamente de la naturaleza: agricultura, ganadería, pesca y minería. El <b>sector secundario</b> transforma esas materias primas en productos, a través de la industria y la construcción. El <b>sector terciario</b> ofrece servicios: comercio, turismo, educación, sanidad o transporte. Cada comunidad autónoma de España destaca en unos sectores u otros según sus recursos naturales.", "diagram": "<b>Sector primario</b>: agricultura, pesca, ganadería, minería<br><b>Sector secundario</b>: industria, fábricas, construcción<br><b>Sector terciario</b>: turismo, comercio, servicios, educación"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Clasifica la actividad", "q": "¿A qué sector económico pertenece un pescador que faena en las costas de Galicia?", "opts": [{"t": "Sector primario", "ok": true}, {"t": "Sector secundario", "ok": false}, {"t": "Sector terciario", "ok": false}, {"t": "No pertenece a ningún sector", "ok": false}], "okMsg": "¡Exacto! Pescar es obtener un recurso directamente de la naturaleza, por eso es sector primario.", "noMsg": "Piénsalo de nuevo: el pescador obtiene el pescado directamente del mar, sin transformarlo ni vender un servicio."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Tu mapa económico", "body": "Empieza a construir tu infografía final sobre la economía de España.", "prompt": "Dibuja un mapa sencillo de España y señala con símbolos (un tractor, una fábrica, una sombrilla) al menos tres actividades económicas distintas que conozcas de diferentes zonas del país."}]},
  "p5:May:2": {"title": "La economía de mi tierra", "steps": [{"type": "hook", "kicker": "Investigación económica", "h": "¿Sabes de qué vive la gente en tu comunidad autónoma?", "scenario": "Cada región de España tiene una vocación económica propia: unas viven del mar, otras del campo, otras de la industria o del turismo.", "body": "Esta semana te conviertes en <b>investigador económico</b> de tu propia comunidad autónoma para descubrir cuál es su actividad principal."}, {"type": "theory", "kicker": "Recursos naturales y comunidades", "h": "La riqueza de cada región", "body": "España tiene una <b>gran diversidad de recursos naturales</b>: el interior cuenta con grandes llanuras para el cereal, el norte tiene pastos para la ganadería, el Mediterráneo ofrece sol y playas para el turismo, y algunas zonas concentran industria y tecnología. Conocer los recursos de tu comunidad te ayuda a entender por qué allí se trabaja principalmente en unos sectores y no en otros.", "diagram": "<b>Interior</b>: cereal y ganadería<br><b>Costas</b>: pesca y turismo<br><b>Zonas industriales</b>: fábricas y tecnología<br><b>Cada comunidad</b>: su propia mezcla de recursos"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Deduce el sector principal", "q": "Si tu comunidad autónoma tiene muchas playas y recibe millones de visitantes cada verano, ¿qué sector será probablemente el más importante?", "opts": [{"t": "Sector terciario (turismo)", "ok": true}, {"t": "Sector primario (pesca)", "ok": false}, {"t": "Sector secundario (industria)", "ok": false}, {"t": "No se puede saber nunca", "ok": false}], "okMsg": "¡Correcto! Cuando el turismo mueve la economía de una región, hablamos del sector terciario o de servicios.", "noMsg": "Recuerda: recibir visitantes y ofrecerles alojamiento, ocio o restauración es un servicio, es decir, sector terciario."}, {"type": "reflect", "kicker": "Investiga tu comunidad", "h": "Datos reales de mi región", "body": "Sigue construyendo tu infografía con información real de tu comunidad.", "prompt": "Investiga (pregunta a un adulto o busca con ayuda) cuál es la actividad económica principal de tu comunidad autónoma y escribe tres datos concretos que la expliquen."}]},
  "p5:May:3": {"title": "¿El turismo tiene un límite?", "steps": [{"type": "hook", "kicker": "A debate", "h": "¿El turismo siempre es bueno para una ciudad?", "scenario": "En verano, ciudades como Barcelona o Palma de Mallorca reciben tantos visitantes que a veces hay más turistas que vecinos en sus calles.", "body": "El turismo trae dinero y empleo, pero también puede traer problemas. Esta semana analizarás los <b>dos lados</b> del turismo masivo."}, {"type": "theory", "kicker": "Oportunidades y retos", "h": "El turismo tiene ventajas... y desafíos", "body": "España es uno de los países más visitados del mundo gracias a su sol, sus playas, su cultura y su historia. El turismo genera <b>empleo y riqueza</b> para millones de familias. Pero el turismo masivo también puede provocar <b>subida de precios de la vivienda</b>, saturación de servicios públicos y presión sobre el medio ambiente. Encontrar el equilibrio es uno de los grandes retos económicos de España.", "diagram": "<b>Ventajas del turismo</b>: empleo, ingresos, difusión de la cultura<br><b>Retos del turismo masivo</b>: precios altos, saturación, impacto ambiental"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Identifica el reto", "q": "¿Cuál de estas es una consecuencia NEGATIVA que puede tener el turismo masivo en una ciudad?", "opts": [{"t": "Que suba mucho el precio de los alquileres para los vecinos", "ok": true}, {"t": "Que se creen nuevos empleos en hostelería", "ok": false}, {"t": "Que aumenten los ingresos de los comercios locales", "ok": false}, {"t": "Que se dé a conocer la cultura española en el mundo", "ok": false}], "okMsg": "Así es: cuando hay demasiada demanda turística, la vivienda puede encarecerse y complicar la vida de los propios vecinos.", "noMsg": "Las otras opciones son beneficios del turismo. Piensa en qué le ocurre a un vecino cuando la vivienda se encarece por la presión turística."}, {"type": "reflect", "kicker": "Debate en familia o en clase", "h": "Dos caras de una moneda", "body": "Organiza un pequeño debate sobre el turismo masivo con tu familia o tus compañeros.", "prompt": "Escribe al menos dos argumentos a favor del turismo y dos argumentos en contra del turismo masivo. Después, defiende oralmente cada postura ante un adulto o tus compañeros."}]},
  "p5:May:4": {"title": "El poder para hacer las riquezas", "steps": [{"type": "hook", "kicker": "La fuente de la riqueza", "h": "¿Quién nos da realmente el poder de prosperar?", "scenario": "Después de estudiar los sectores económicos, los recursos naturales y el turismo, llega el momento de preguntarnos de dónde viene, en el fondo, la capacidad de generar riqueza.", "body": "La Biblia nos recuerda que detrás de todo trabajo, recurso natural y talento humano está <b>Dios como dador de todo bien</b>."}, {"type": "theory", "kicker": "Verdad bíblica", "h": "\"Él te da el poder para hacer las riquezas\"", "body": "En <b>Deuteronomio 8:18</b> se lee: \"Acuérdate del Señor tu Dios, porque Él te da el poder para hacer las riquezas.\" Esto no significa que no debamos trabajar ni esforzarnos, sino que reconozcamos que nuestras capacidades, los recursos naturales de España y las oportunidades que tenemos vienen, en última instancia, de Dios. La economía es un regalo que debemos administrar con sabiduría y agradecimiento.", "diagram": "<b>Recursos naturales</b> + <b>trabajo humano</b> + <b>bendición de Dios</b> = riqueza de una nación<br>Deuteronomio 8:18"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Recuerda el versículo", "q": "Según Deuteronomio 8:18, ¿quién da el poder para generar riquezas?", "opts": [{"t": "Dios", "ok": true}, {"t": "El gobierno", "ok": false}, {"t": "El turismo", "ok": false}, {"t": "La suerte", "ok": false}], "okMsg": "¡Correcto! El versículo nos recuerda que debemos acordarnos del Señor como fuente del poder para prosperar.", "noMsg": "Vuelve a leer el versículo: \"Acuérdate del Señor tu Dios, porque Él te da el poder para hacer las riquezas.\""}, {"type": "reflect", "kicker": "Proyecto final", "h": "Tu infografía económica", "body": "Es momento de terminar tu proyecto final del mes.", "prompt": "Completa tu 'Infografía económica de mi comunidad autónoma': incluye el mapa de actividades, los datos de tu comunidad, una reflexión sobre el turismo y una frase final que relacione tu trabajo con Deuteronomio 8:18."}]},
  "p5:Jun:1": {"title": "Un idioma gigante", "steps": [{"type": "hook", "kicker": "Un idioma gigante", "h": "¿Sabías que el español se habla en 22 países?", "scenario": "Cuando hablas español, te estás comunicando con personas de México, Argentina, Colombia, Guinea Ecuatorial y muchos otros lugares.", "body": "Esta semana descubrirás la <b>dimensión mundial</b> del idioma que hablas cada día."}, {"type": "theory", "kicker": "El español en cifras", "h": "580 millones de hispanohablantes", "body": "El español es lengua oficial en <b>22 países</b>, repartidos entre Europa, América y África. En total, más de <b>580 millones de personas</b> hablan español en el mundo, ya sea como lengua materna o aprendida. Desde España hasta Argentina, pasando por México, Colombia y Guinea Ecuatorial, el español conecta a millones de personas de culturas muy diferentes.", "diagram": "<b>580 millones</b> de hispanohablantes<br><b>22 países</b> con el español como lengua oficial<br>Europa + América + África"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Un dato clave", "q": "Aproximadamente, ¿en cuántos países es el español lengua oficial?", "opts": [{"t": "22 países", "ok": true}, {"t": "5 países", "ok": false}, {"t": "50 países", "ok": false}, {"t": "100 países", "ok": false}], "okMsg": "¡Exacto! El español es lengua oficial en 22 países de Europa, América y África.", "noMsg": "El dato correcto es 22 países. ¡Es un número más grande de lo que muchos imaginan!"}, {"type": "reflect", "kicker": "Explora el mapa", "h": "Localiza el español en el mundo", "body": "Empieza a construir tu mapa del español en el mundo.", "prompt": "Dibuja o busca un mapamundi y señala con un color los países donde el español es lengua oficial. Intenta nombrar al menos 8 de esos 22 países sin ayuda."}]},
  "p5:Jun:2": {"title": "Un mismo idioma, mil acentos", "steps": [{"type": "hook", "kicker": "Un mismo idioma, mil acentos", "h": "¿'Ordenador' o 'computadora'? ¿'Coche' o 'carro'?", "scenario": "Un niño de España habla de coger el autobús, mientras un niño de México o Argentina usaría otras palabras para contar lo mismo.", "body": "Aunque todos hablamos español, existen <b>variedades</b> según el país. Esta semana investigarás algunas diferencias curiosas."}, {"type": "theory", "kicker": "Variedades del español", "h": "Peninsular e hispanoamericano", "body": "El <b>español peninsular</b> (el de España) y el <b>español hispanoamericano</b> comparten la misma gramática básica, pero tienen diferencias de vocabulario, pronunciación y expresiones. Por ejemplo, en España se dice 'ordenador' y en muchos países de América 'computadora'; en España 'coche' y en otros lugares 'carro' o 'auto'. Estas diferencias no separan el idioma, ¡lo enriquecen!", "diagram": "<b>España</b>: ordenador, coche, patata<br><b>México/Argentina</b>: computadora, carro/auto, papa<br>Mismo idioma, distintas variedades"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Traduce la variedad", "q": "En España se dice 'ordenador'. ¿Cómo se dice habitualmente en México o Argentina?", "opts": [{"t": "Computadora", "ok": true}, {"t": "Teléfono", "ok": false}, {"t": "Televisor", "ok": false}, {"t": "Tableta", "ok": false}], "okMsg": "¡Correcto! 'Computadora' es la forma habitual en gran parte de Hispanoamérica para lo que en España llamamos 'ordenador'.", "noMsg": "La palabra equivalente a 'ordenador' en muchos países hispanoamericanos es 'computadora'."}, {"type": "reflect", "kicker": "Investiga vocabulario", "h": "Palabras distintas, mismo idioma", "body": "Sigue explorando las variedades del español.", "prompt": "Investiga y escribe una lista de 3 palabras que se dicen de forma diferente en España y en México o Argentina (por ejemplo: ordenador/computadora). Pregunta a un adulto o busca ejemplos con ayuda."}]},
  "p5:Jun:3": {"title": "Escribir para conectar", "steps": [{"type": "hook", "kicker": "Escribir para conectar", "h": "¿Te gustaría tener un amigo por carta en otro país hispanohablante?", "scenario": "Un niño en Perú, otro en Guinea Ecuatorial y tú en España podríais entenderos perfectamente escribiendo en español, aunque nunca os hayáis visto.", "body": "Esta semana usarás el español como <b>puente</b> para conectar con alguien de otra cultura."}, {"type": "theory", "kicker": "La lengua de cultura y fe", "h": "El español como lengua de encuentro", "body": "El español no solo sirve para comunicarnos: también es una <b>lengua de cultura</b>, presente en la literatura, la música y el cine, y una <b>lengua de fe</b>, usada para compartir la Biblia y el mensaje cristiano en millones de hogares hispanohablantes. Escribir una carta a alguien de otro país hispanohablante es una forma sencilla de vivir esa conexión.", "diagram": "<b>Español</b> = lengua de comunicación<br>+ lengua de cultura (libros, música)<br>+ lengua de fe (Biblia, iglesias)"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Más que comunicación", "q": "Según lo estudiado, además de servir para comunicarnos, ¿para qué más se usa el idioma español en muchos países?", "opts": [{"t": "Para compartir cultura y fe", "ok": true}, {"t": "Solo para hacer negocios", "ok": false}, {"t": "Solo para viajar", "ok": false}, {"t": "No tiene otros usos", "ok": false}], "okMsg": "¡Correcto! El español es también una lengua de cultura y de fe, compartida por millones de personas.", "noMsg": "Recuerda: el español sirve además para transmitir literatura, música y el mensaje de la Biblia."}, {"type": "reflect", "kicker": "Tu carta", "h": "Escribe a un hispanohablante de otro país", "body": "Es hora de escribir tu propia carta.", "prompt": "Escribe una carta de 15 oraciones dirigida a un niño o niña hispanohablante de otro país. Cuéntale cómo es tu vida en España, qué te gusta de tu país y hazle alguna pregunta sobre el suyo."}]},
  "p5:Jun:4": {"title": "Una lengua pura para los pueblos", "steps": [{"type": "hook", "kicker": "Una lengua pura para todos los pueblos", "h": "¿Puede un idioma unir a personas de países tan distintos?", "scenario": "Has descubierto que el español conecta a 580 millones de personas en 22 países. La Biblia también habla de un idioma que Dios usará para unir a los pueblos.", "body": "Cerramos el mes conectando el español con una promesa bíblica muy especial."}, {"type": "theory", "kicker": "Verdad bíblica", "h": "\"Daré a los pueblos una lengua pura\"", "body": "En <b>Sofonías 3:9</b> se lee: \"Entonces devolveré a los pueblos una lengua pura.\" Este versículo habla de cómo Dios quiere unir a las naciones para que le adoren con un mismo propósito y corazón. El español, como lengua compartida por tantos pueblos y culturas, puede ser una herramienta para llevar ese mensaje de unidad y fe a millones de personas, tal como hiciste con tu carta esta semana.", "diagram": "<b>Sofonías 3:9</b>: \"lengua pura\" para los pueblos<br>580 millones hablan español<br>El idioma como puente para la misión"}, {"type": "quiz", "kicker": "Comprueba lo aprendido", "h": "Recuerda el versículo", "q": "Según Sofonías 3:9, ¿qué promete Dios devolver a los pueblos?", "opts": [{"t": "Una lengua pura", "ok": true}, {"t": "Más riquezas", "ok": false}, {"t": "Más territorio", "ok": false}, {"t": "Más ejércitos", "ok": false}], "okMsg": "¡Correcto! Dios promete devolver a los pueblos una lengua pura para que puedan adorarle unidos.", "noMsg": "Vuelve a leer el versículo: \"Entonces devolveré a los pueblos una lengua pura.\""}, {"type": "reflect", "kicker": "Proyecto final", "h": "El castellano como herramienta de misión", "body": "Termina tu proyecto final del mes.", "prompt": "Completa tu entregable 'El castellano como herramienta de misión': incluye el mapa del español en el mundo, tu carta de 15 oraciones y una frase final que relacione el versículo de Sofonías 3:9 con el valor de compartir el idioma español."}]},
  "p5:Jul:1": {"title": "Mi Ensayo Final: Ser Español y Cristiano en el Mundo", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 1", "h": "¿Qué dirías si el mundo entero te preguntara quién eres?", "scenario": "Imagina que te invitan a un programa de televisión internacional y un periodista te pregunta: '¿Qué significa para ti ser español y cristiano hoy?'. Tienes solo un minuto para responder con claridad y con el corazón.", "body": "Durante todo este curso has viajado por la historia de España: el <b>Imperio de Carlos I y Felipe II</b>, el lugar de España en Europa, las aventuras de <b>Colón</b> y la defensa de los indígenas de <b>Bartolomé de las Casas</b>, la belleza del <b>Siglo de Oro</b> y la fuerza del español que hoy hablan cientos de millones de personas. Ha llegado el momento de unir todo eso en tus propias palabras y escribir el ensayo final de tu curso."}, {"type": "theory", "kicker": "Cómo se construye un buen argumento", "h": "Un ensayo con cabeza, corazón y estructura", "body": "Un buen ensayo argumentativo tiene tres partes: la <b>introducción</b> (presentas tu idea principal), el <b>desarrollo</b> (explicas tus razones con ejemplos: historia, fe, lengua, cultura) y la <b>conclusión</b> (resumes y dejas una idea fuerte). Tu ensayo tendrá <b>15 oraciones</b> en total, y puedes apoyarte en lo aprendido: la identidad cristiana de España, su papel en la historia de Europa y del mundo, y el regalo del idioma español que hoy une a millones de personas en los cinco continentes.", "diagram": "<b>INTRODUCCIÓN</b> → presento la idea<br><b>DESARROLLO</b> → historia + fe + lengua + cultura<br><b>CONCLUSIÓN</b> → idea final fuerte<br><b>TOTAL</b>: 15 oraciones"}, {"type": "quiz", "kicker": "Repaso exprés", "h": "¿Qué han conocido en el mundo gracias a la historia de España?", "q": "¿Cuál de estos elementos es un ejemplo del legado cristiano y cultural de España que llegó al mundo entero?", "opts": [{"t": "El idioma español, hablado hoy por cientos de millones de personas", "ok": true}, {"t": "Un videojuego inventado en el siglo XXI", "ok": false}, {"t": "Una receta de comida rápida moderna", "ok": false}, {"t": "Un idioma que ya no se habla en ningún país", "ok": false}], "okMsg": "¡Exacto! El español y la fe cristiana viajaron juntos por América y el mundo, y hoy siguen siendo un regalo vivo.", "noMsg": "Piénsalo de nuevo: recuerda todo lo que aprendiste sobre Colón, el Imperio y el idioma español que se extendió por el mundo."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu ensayo final", "body": "Ha llegado el momento de escribir con tus propias palabras qué significa para ti ser español y cristiano en un mundo globalizado. Usa lo que aprendiste sobre historia, fe y lengua durante todo el curso.", "prompt": "Escribe un ensayo de exactamente <b>15 oraciones</b> titulado 'Qué significa ser español cristiano en el mundo globalizado'. Incluye: una introducción con tu idea principal, al menos tres razones apoyadas en la historia o la fe (por ejemplo el Imperio, Colón y Bartolomé de las Casas, el Siglo de Oro o el idioma español), y una conclusión que exprese con fuerza tu identidad."}]},
  "p5:Jul:2": {"title": "Mi Voz, Mi Turno: Presento Ante Mi Familia", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 2", "h": "¿Te atreves a hablar en voz alta durante 6 minutos?", "scenario": "Reúne a tu familia en el salón, respira hondo y prepárate: hoy no escribes, hoy hablas. Tu ensayo, escrito la semana pasada, va a cobrar vida con tu voz.", "body": "La semana pasada escribiste tu ensayo sobre ser español y cristiano en el mundo globalizado. Ahora toca un reto distinto: <b>compartirlo en voz alta</b>. A lo largo del curso muchos personajes históricos tuvieron que defender sus ideas hablando con valentía, como Bartolomé de las Casas ante la corte de Carlos I. Hoy tú también vas a defender tus ideas con tu propia voz."}, {"type": "theory", "kicker": "El arte de hablar en público", "h": "Cómo presentar con claridad y seguridad", "body": "Presentar bien no es solo leer rápido: es <b>comunicar con el corazón</b>. Recuerda mirar a tu familia a los ojos de vez en cuando, hablar despacio y con voz clara, hacer pequeñas pausas entre ideas, y mostrar con tu tono que crees en lo que dices. Al final, tu familia te hará preguntas: escúchalas con atención y responde con calma, usando lo que aprendiste durante todo el año.", "diagram": "<b>VOZ CLARA</b> + <b>RITMO PAUSADO</b> + <b>MIRADA</b> + <b>SEGURIDAD</b> = presentación de 6 minutos<br>Al final: preguntas de la familia"}, {"type": "quiz", "kicker": "Repaso exprés", "h": "¿Qué necesita una buena presentación oral?", "q": "¿Cuál de estas actitudes ayuda MÁS a comunicar bien un ensayo en voz alta?", "opts": [{"t": "Hablar despacio, con voz clara y mirando a quien te escucha", "ok": true}, {"t": "Leer lo más rápido posible sin pausas", "ok": false}, {"t": "Hablar mirando siempre al suelo", "ok": false}, {"t": "No prepararse porque ya está escrito", "ok": false}], "okMsg": "¡Así es! Una buena presentación se prepara con calma, voz clara y contacto con quien escucha.", "noMsg": "Recuerda: hablar despacio, con voz clara y mirando a tu familia es lo que hace fuerte una presentación."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Presenta tu ensayo ante tu familia", "body": "Practica primero en voz baja, cronometra el tiempo, y después reúne a tu familia para tu gran presentación final.", "prompt": "Lee o expón tu ensayo completo en voz alta ante tu familia durante aproximadamente <b>6 minutos</b>. Al terminar, invita a que te hagan al menos dos preguntas sobre lo que dijiste y respóndelas con tus propias palabras. Escribe después dos frases sobre cómo te sentiste al compartir tu identidad en voz alta."}]},
  "p5:Jul:3": {"title": "Un Mapa de Todo lo Aprendido", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 3", "h": "¿Podrías dibujar todo un curso en una sola hoja?", "scenario": "Imagina que tienes que resumir en un solo mapa —con líneas, dibujos y palabras clave— todo un año de historia, geografía y lengua española. ¿Por dónde empezarías?", "body": "Este curso ha sido un largo viaje: el <b>Imperio español</b> de Carlos I y Felipe II, el lugar de <b>España en Europa</b>, la llegada de Colón a América y la defensa de los indígenas de Bartolomé de las Casas, la poesía y el <b>Siglo de Oro</b>, la economía de España y el <b>español como lengua del mundo</b>. Esta semana vas a construir un mapa mental que conecte todas esas piezas en una sola imagen."}, {"type": "theory", "kicker": "Cómo organizar ideas en un mapa mental", "h": "Tres ramas para un año entero", "body": "Un buen mapa mental parte de una <b>idea central</b> —España— y se abre en ramas. Puedes organizar el tuyo en tres grandes ramas: <b>Historia</b> (Imperio, Carlos I, Felipe II, Colón, Bartolomé de las Casas), <b>Geografía</b> (España y Europa, su territorio y su economía) y <b>Lengua</b> (poesía del Siglo de Oro, el español hablado en el mundo). Usa colores, dibujos pequeños y palabras clave, no frases largas.", "diagram": "<b>ESPAÑA</b> (centro)<br>→ <b>HISTORIA</b>: Imperio, Carlos I, Felipe II, Colón, Bartolomé de las Casas<br>→ <b>GEOGRAFÍA</b>: España y Europa, economía<br>→ <b>LENGUA</b>: Siglo de Oro, poesía, español en el mundo"}, {"type": "quiz", "kicker": "Repaso exprés", "h": "¿Cómo se organiza un mapa mental?", "q": "¿Qué característica debe tener un buen mapa mental?", "opts": [{"t": "Una idea central con ramas organizadas en palabras clave y dibujos", "ok": true}, {"t": "Un texto largo escrito en párrafos, sin dibujos ni ramas", "ok": false}, {"t": "Solo números y fechas, sin ninguna palabra", "ok": false}, {"t": "Una lista de la compra sin relación con el tema", "ok": false}], "okMsg": "¡Correcto! Un mapa mental parte de una idea central y se organiza en ramas claras con palabras clave.", "noMsg": "Recuerda: un mapa mental tiene una idea central y ramas con palabras clave y dibujos, no párrafos largos."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Dibuja tu mapa mental del curso", "body": "En una hoja grande o en tu cuaderno, dibuja el mapa mental que resuma todo lo aprendido este año.", "prompt": "Crea un <b>mapa mental</b> con 'España' en el centro y al menos tres ramas: <b>Historia</b> (incluye el Imperio, Carlos I, Felipe II, Colón y Bartolomé de las Casas), <b>Geografía</b> (España y Europa, su economía) y <b>Lengua</b> (el Siglo de Oro, la poesía clásica y el español en el mundo). Añade dibujos pequeños y colores para cada rama."}]},
  "p5:Jul:4": {"title": "La Sal y la Luz: El Regalo de España al Mundo", "steps": [{"type": "hook", "kicker": "Proyecto Final · Semana 4 · Cierre de Curso", "h": "¿Qué regalo ha dado Dios a España para bendecir al mundo?", "scenario": "Después de todo un año de historia, geografía y lengua, llega la última pregunta del curso, quizás la más importante de todas.", "body": "Jesús dijo a sus discípulos: '<b>Vosotros sois la sal de la tierra y la luz del mundo</b>' (Mt 5:13). Durante este curso has descubierto cómo España, con su historia, su lengua y su fe, ha llevado 'sal y luz' a muchos rincones del planeta: desde el idioma español que hoy hablan cientos de millones de personas, hasta la defensa de la dignidad humana que hizo Bartolomé de las Casas, pasando por la belleza del Siglo de Oro. Hoy cierras el curso reflexionando sobre ese regalo."}, {"type": "theory", "kicker": "Ser sal y luz hoy", "h": "El legado de España, un regalo para compartir", "body": "Ser 'sal' significa dar sabor y conservar lo bueno; ser 'luz' significa mostrar el camino con el ejemplo. España ha compartido con el mundo su <b>lengua</b> (el español, hoy hablado en decenas de países), su <b>fe cristiana</b> (que llegó con misioneros y defensores como Bartolomé de las Casas) y su <b>cultura</b> (la poesía y el arte del Siglo de Oro). Ese es el regalo que Dios permitió que España diera al mundo, y tú, como niño o niña español y cristiano, también puedes seguir siendo sal y luz allí donde estés.", "diagram": "<b>SAL</b>: da sabor, conserva lo bueno<br><b>LUZ</b>: muestra el camino<br>Regalos de España al mundo → <b>lengua</b> + <b>fe</b> + <b>cultura</b><br>Mt 5:13"}, {"type": "quiz", "kicker": "Repaso exprés final", "h": "¿Qué significa el versículo de Mateo 5:13?", "q": "Según Mateo 5:13, ¿qué quiso decir Jesús al llamar a sus seguidores 'sal de la tierra y luz del mundo'?", "opts": [{"t": "Que están llamados a dar buen ejemplo y ayudar a los demás", "ok": true}, {"t": "Que deben esconder su fe y no mostrarla nunca", "ok": false}, {"t": "Que solo importa lo que se aprende en la escuela", "ok": false}, {"t": "Que la sal y la luz no tienen ningún significado especial", "ok": false}], "okMsg": "¡Muy bien! Ser sal y luz significa vivir de forma que ayude y iluminar a los demás, con el ejemplo y la fe.", "noMsg": "Repasa el versículo: ser sal y luz significa dar buen ejemplo y ayudar a otros con la propia vida y fe."}, {"type": "reflect", "kicker": "Cierre del curso", "h": "Tu reflexión final y un agradecimiento", "body": "Este es el último paso de todo tu curso de 5º de Primaria. Tómate tu tiempo para responder con sinceridad y celebrar todo lo aprendido.", "prompt": "Responde por escrito: <b>¿Qué regalo ha dado Dios a España para bendecir al mundo?</b> Menciona al menos dos elementos (por ejemplo la lengua española, la fe cristiana, la defensa de la dignidad humana o el arte del Siglo de Oro) y explica cómo tú, personalmente, puedes ser 'sal y luz' en tu propia vida. Termina tu reflexión con una frase de agradecimiento por todo lo aprendido este curso."}]},
});
